   "转小火，下入肉片轻轻滑散，肉片变色熟透后连汤汁一起倒入垫蔬菜的碗中。",
   "表面铺满干辣椒段、干花椒；烧滚烫热油，均匀淋在辣椒花椒上激发出香味。\n贴士：肉片不要久煮，防止变老；热油一定要烧至冒烟香气才足。"
